      "path": "package.json",
      "content": "{\n  \"name\": \"ds-harness-remote\",\n  \"version\": \"0.6.4\",\n  \"description\": \"P2P-based, end-to-end encrypted remote access to DeepSeek Harness, CodeX, Claude Code, Pi, and other workspaces from web and mobile clients.\",\n  \"keywords\": [\n    \"deepseek\",\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"codex\",\n    \"remote-development\",\n    \"end-to-end-encryption\",\n    \"webrtc\"\n  ],\n  \"homepage\": \"https://github.com/liguobao/ds-harness-remote#readme\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/liguobao/ds-harness-remote.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/liguobao/ds-harness-remote/issues\"\n  },\n  \"author\": \"liguobao <lgb835485368@gmail.com>\",\n  \"license\": \"MIT\",\n  \"type\": \"module\",\n  \"main\": \"./index.js\",\n  \"bin\": {\n    \"ds-harness-remote\": \"./packages/plugin/bin/ds-harness-remote.js\"\n  },\n  \"types\": \"./packages/plugin/public.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./packages/plugin/public.d.ts\",\n      \"import\": \"./index.js\",\n      \"default\": \"./index.js\"\n    },\n    \"./client\": \"./packages/plugin/dist/client.github.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./package.json\": \"./package.json\",\n    \"./icon\": \"./icon.png\"\n  },\n  \"files\": [\n    \"index.js\",\n    \"packages/plugin/dist/index.js\",\n    \"packages/plugin/dist/client.github.js\",\n    \"packages/plugin/bin/ds-harness-remote.js\",\n    \"packages/plugin/public.d.ts\",\n    \"packages/plugin/LICENSE\",\n    \"dsh-plugin.json\",\n    \"cordis.patch.yml\",\n    \"locale/\",\n    \"README.md\",\n    \"package.json\",\n    \"icon.png\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-sidebar\",\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-settings-general\",\n        \"@deepseek-ai/dsh-client-ui-plugin-manager\",\n        \"@deepseek-ai/dsh-client-ui-settings-plugin-inventory\",\n        \"@deepseek-ai/dsh-client-ui-settings-plugins\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"packageManager\": \"pnpm@9.15.4\",\n  \"pnpm\": {\n    \"overrides\": {\n      \"@xmldom/xmldom@0.8\": \"^0.8.15\",\n      \"@xmldom/xmldom@0.9\": \"^0.9.12\",\n      \"brace-expansion@5\": \"^5.0.12\",\n      \"compression@1\": \"^1.8.2\",\n      \"js-yaml@4\": \"^4.3.2\",\n      \"shell-quote@1\": \"^1.11.0\",\n      \"source-map-js@1\": \"^1.2.2\"\n    }\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"^3.18.5\",\n    \"qrcode\": \"^1.5.4\",\n    \"zod\": \"^4.6.7\",\n    \"ws\": \"^8.21.3\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \">=4.0.1 <5 || >=4.0.5-alpha.1 <4.0.6-0\",\n    \"@deepseek-ai/dsh-api-gateway\": \">=0.2.0-rc.1 <0.3.0-0 || >=0.2.1-0 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-connection\": \">=0.2.0-rc.1 <0.3.0-0 || >=0.2.1-0 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-locale\": \">=0.2.0-rc.1 <0.3.0-0 || >=0.2.1-0 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-sidebar\": \">=0.2.0-rc.1 <0.3.0-0 || >=0.2.1-0 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \">=0.2.0-rc.1 <0.3.0-0 || >=0.2.1-0 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \">=0.2.0-rc.1 <0.3.0-0 || >=0.2.1-0 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-settings-plugins\": \">=0.2.0-rc.1 <0.3.0-0 || >=0.2.1-0 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\",\n    \"@deepseek-ai/dsh-settings\": \">=0.2.0-rc.1 <0.3.0-0 || >=0.2.1-0 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\",\n    \"react\": \">=18.2.0 <19\",\n    \"@deepseek-ai/dsh-client-ui-settings-general\": \">=0.2.0-rc.1 <0.3.0-0 || >=0.2.1-0 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": \">=0.2.0-rc.1 <0.3.0-0 || >=0.2.1-0 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-settings-plugin-inventory\": \">=0.2.0-rc.1 <0.3.0-0 || >=0.2.1-0 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-client-connection\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-locale\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-sidebar\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-slots\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-settings\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-settings-plugins\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-settings-general\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-settings-plugin-inventory\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.1.0\",\n    \"@deepseek-ai/cordis-plugin-include\": \"1.1.0\",\n    \"@deepseek-ai/cordis-plugin-loader\": \"1.1.0\",\n    \"@deepseek-ai/dsh-api-gateway\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-api-remote-access\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-typert-registry\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-brand\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-connection\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-settings-plugins\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-sidebar\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-scope\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-session\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-settings\": \"0.2.2-rc.1\",\n    \"@types/node\": \"^24.9.0\",\n    \"tsx\": \"^4.19.2\",\n    \"typescript\": \"^5.7.3\",\n    \"vitest\": \"^2.1.8\",\n    \"@types/ws\": \"^8.18.1\",\n    \"@deepseek-ai/dsh-client-ui-settings-general\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-settings-plugin-inventory\": \"0.2.2-rc.1\"\n  },\n  \"optionalDependencies\": {\n    \"@roamhq/wrtc\": \"0.10.0\"\n  }\n}\n"
